import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin } from './helpers';

test.describe(`team member: create a new issue and assign it to a teammate`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member creates a task and assigns it, every team member sees the new task with its assignee within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);

    // Put both nodes in one shared workspace so B can observe A's writes.
    await inviteAndJoin(pageA, pageB);

    // A creates a category (required before a task can be filed) then a task
    // assigned to a teammate.
    await pageA.getByTestId('field-name').fill('Backend');
    await pageA.getByTestId('action-create_category').click();
    await expect(pageA.locator('[data-testid^="item-category-"]').filter({ hasText: 'Backend' })).toBeVisible({ timeout: 10_000 });

    await pageA.getByTestId('field-title').fill('Fix login bug');
    await pageA.getByTestId('field-description').fill("Users can't log in on Safari");
    await pageA.getByTestId('field-assignee').fill('bob');
    await pageA.getByTestId('action-create_task').click();

    // B (a different node/identity) sees the new task with its assignee
    // within 5s, with no action on B's part.
    const taskOnB = pageB.locator('[data-testid^="item-task-"]').filter({ hasText: 'Fix login bug' });
    await expect(taskOnB).toBeVisible({ timeout: 5_000 });
    await expect(taskOnB).toContainText('bob');

    // Re-assigning to a different teammate via the dedicated assign control
    // also propagates to every team member within 5s.
    const taskOnA = pageA.locator('[data-testid^="item-task-"]').filter({ hasText: 'Fix login bug' });
    await taskOnA.click();
    const detailDialogA = pageA.getByRole('dialog');
    await detailDialogA.getByTestId('field-assignee').fill('carol');
    await detailDialogA.getByTestId('action-assign_task').click();
    await expect(taskOnB).toContainText('carol', { timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });
});
